1	import { TraceInfo } from '../core/entities/trace_info';
2	import { Trace } from '../core/entities/trace';
3	import {
4	  CreateExperiment,
5	  DeleteExperiment,
6	  GetExperimentByName,
7	  GetTraceInfoV3,
8	  StartTraceV3,
9	} from './spec';
10	import { makeRequest, MlflowHttpError } from './utils';
11	import { TraceData } from '../core/entities/trace_data';
12	import { ArtifactsClient, getArtifactsClient } from './artifacts';
13	import { AuthProvider, HeadersProvider } from '../auth';
14	
15	/**
16	 * Client for MLflow tracing operations.
17	 *
18	 * Supports multiple authentication methods:
19	 * - Databricks: PAT tokens, OAuth M2M, Azure CLI/MSI, Google Cloud
20	 * - OSS MLflow: Basic auth, Bearer tokens, or no auth
21	 */
22	export class MlflowClient {
23	  /** Client implementation to upload/download trace data artifacts */
24	  private artifactsClient: ArtifactsClient;
25	
26	  /** Headers provider for authenticated requests */
27	  private headersProvider: HeadersProvider;
28	
29	  /** Host URL for API requests */
30	  private hostUrl: string;
31	
32	  /**
33	   * Creates a new MlflowClient.
34	   *
35	   * @param trackingUri - The tracking URI (e.g., "databricks", "http://localhost:5000")
36	   * @param authProvider - The authentication provider to get tokens for authenticated requests
37	   */
38	  constructor(options: { trackingUri: string; authProvider: AuthProvider }) {
39	    this.headersProvider = options.authProvider.getHeadersProvider();
40	    this.hostUrl = options.authProvider.getHost();
41	
42	    this.artifactsClient = getArtifactsClient({
43	      trackingUri: options.trackingUri,
44	      host: this.hostUrl,
45	      authProvider: options.authProvider,
46	    });
47	  }
48	
49	  /**
50	   * Get the host URL for this client.
51	   */
52	  getHost(): string {
53	    return this.hostUrl;
54	  }
55	
56	  // === TRACE LOGGING METHODS ===
57	  /**
58	   * Create a new TraceInfo record in the backend store.
59	   * Corresponding to the Python SDK's start_trace_v3() method.
60	   *
61	   * Note: the backend API is named as "Start" due to unfortunate miscommunication.
62	   * The API is indeed called at the "end" of a trace, not the "start".
63	   */
64	  async createTrace(traceInfo: TraceInfo): Promise<TraceInfo> {
65	    const url = StartTraceV3.getEndpoint(this.hostUrl);
66	    const payload: StartTraceV3.Request = { trace: { trace_info: traceInfo.toJson() } };
67	    const response = await makeRequest<StartTraceV3.Response>(
68	      'POST',
69	      url,
70	      this.headersProvider,
71	      payload,
72	    );
73	    return TraceInfo.fromJson(response.trace.trace_info);
74	  }
75	
76	  // === TRACE RETRIEVAL METHODS ===
77	  /**
78	   * Get a single trace by ID
79	   * Fetches both trace info and trace data from backend
80	   * Corresponds to Python: client.get_trace()
81	   */
82	  async getTrace(traceId: string): Promise<Trace> {
83	    const traceInfo = await this.getTraceInfo(traceId);
84	    const traceData = await this.artifactsClient.downloadTraceData(traceInfo);
85	    return new Trace(traceInfo, traceData);
86	  }
87	
88	  /**
89	   * Get trace info using V3 API
90	   * Endpoint: GET /api/3.0/mlflow/traces/{trace_id}
91	   */
92	  async getTraceInfo(traceId: string): Promise<TraceInfo> {
93	    const url = GetTraceInfoV3.getEndpoint(this.hostUrl, traceId);
94	    const response = await makeRequest<GetTraceInfoV3.Response>('GET', url, this.headersProvider);
95	
96	    // The V3 API returns a Trace object with trace_info field
97	    if (response.trace?.trace_info) {
98	      return TraceInfo.fromJson(response.trace.trace_info);
99	    }
100	
101	    throw new Error(`Invalid response format: missing trace_info: ${JSON.stringify(response)}`);
102	  }
103	
104	  /**
105	   * Upload trace data to the artifact store.
106	   */
107	  async uploadTraceData(traceInfo: TraceInfo, traceData: TraceData): Promise<void> {
108	    await this.artifactsClient.uploadTraceData(traceInfo, traceData);
109	  }
110	
111	  // === EXPERIMENT METHODS  ===
112	  /**
113	   * Create a new experiment
114	   */
115	  async createExperiment(
116	    name: string,
117	    artifactLocation?: string,
118	    tags?: Record<string, string>,
119	  ): Promise<string> {
120	    const url = CreateExperiment.getEndpoint(this.hostUrl);
121	    const payload: CreateExperiment.Request = { name, artifact_location: artifactLocation, tags };
122	    const response = await makeRequest<CreateExperiment.Response>(
123	      'POST',
124	      url,
125	      this.headersProvider,
126	      payload,
127	    );
128	    return response.experiment_id;
129	  }
130	
131	  /**
132	   * Get an experiment by name.
133	   */
134	  async getExperimentByName(name: string): Promise<{ experimentId: string; name: string } | null> {
135	    const url = GetExperimentByName.getEndpoint(this.hostUrl, name);
136	    try {
137	      const response = await makeRequest<GetExperimentByName.Response>(
138	        'GET',
139	        url,
140	        this.headersProvider,
141	      );
142	      if (!response.experiment?.experiment_id || !response.experiment?.name) {
143	        return null;
144	      }
145	      return {
146	        experimentId: response.experiment.experiment_id,
147	        name: response.experiment.name,
148	      };
149	    } catch (error) {
150	      if (
151	        error instanceof MlflowHttpError &&
152	        (error.status === 404 || error.errorCode === 'RESOURCE_DOES_NOT_EXIST')
153	      ) {
154	        return null;
155	      }
156	      throw error;
157	    }
158	  }
159	
160	  /**
161	   * Delete an experiment
162	   */
163	  async deleteExperiment(experimentId: string): Promise<void> {
164	    const url = DeleteExperiment.getEndpoint(this.hostUrl);
165	    const payload: DeleteExperiment.Request = { experiment_id: experimentId };
166	    await makeRequest<void>('POST', url, this.headersProvider, payload);
167	  }
168	}
