61	 * text instead of cut-off JSON.
62	 *
63	 * Mirrors the Python SDK's `_get_truncated_preview` in
64	 * `mlflow/tracing/utils/truncation.py`.
65	 */
66	function getTruncatedPreview(inputsOrOutputs: string, role: string): string {
67	  if (!inputsOrOutputs) {
68	    return '';
69	  }
70	
71	  const maxLength = REQUEST_RESPONSE_PREVIEW_MAX_LENGTH;
72	  let content: string | null = null;
73	
74	  try {
75	    const obj = JSON.parse(inputsOrOutputs);
76	    if (obj && typeof obj === 'object') {
77	      const messages = tryExtractMessages(obj as Record<string, unknown>);
78	      if (messages && messages.length > 0) {
79	        const msg = getLastMessageByRole(messages, role);
80	        content = getTextContentFromMessage(msg);
81	      }
82	    }
83	  } catch {
84	    // Not valid JSON — use as-is
85	  }
86	
87	  const preview = content || inputsOrOutputs;
88	  if (preview.length <= maxLength) {
89	    return preview;
90	  }
91	  return preview.slice(0, maxLength - 3) + '...';
