140	function getLastMessageByRole(
141	  messages: Record<string, unknown>[],
142	  role: string,
143	): Record<string, unknown> {
144	  for (let i = messages.length - 1; i >= 0; i--) {
145	    if (messages[i].role === role) {
146	      return messages[i];
147	    }
148	  }
149	  return messages[messages.length - 1];
