152	function getTextContentFromMessage(message: Record<string, unknown>): string | null {
153	  const content = message.content;
154	  if (typeof content === 'string') {
155	    return content;
156	  }
157	  if (Array.isArray(content)) {
158	    for (const part of content) {
159	      if (typeof part === 'string') {
160	        return part;
161	      }
162	      if (
163	        part &&
164	        typeof part === 'object' &&
165	        'type' in (part as Record<string, unknown>) &&
166	        ((part as Record<string, unknown>).type === 'text' ||
167	          (part as Record<string, unknown>).type === 'output_text')
168	      ) {
169	        return (part as Record<string, unknown>).text as string;
170	      }
171	    }
172	  }
173	  return null;
