export const TRACE_ID_V4_PREFIX = 'trace:/';

/**
 * Parse a v4 trace ID string of the form 'trace:/<location>/<otelTraceId>'.
 *
 * Returns a tuple [locationString, otelTraceId]. For non-v4 strings (e.g.
 * 'tr-<id>'), returns [null, rawTraceId]. For strings that begin with
 * 'trace:/' but are structurally malformed (e.g., only one path segment after
 * the prefix, or an empty location segment), throws an error.
 *
 * @param traceId The trace ID string to parse
 */
export function parseTraceIdV4(traceId: string): [string | null, string] {
  if (traceId.startsWith(TRACE_ID_V4_PREFIX)) {
    const segments = traceId.slice(TRACE_ID_V4_PREFIX.length).split('/');
    if (segments.length === 2 && segments[0] && segments[1]) {
      return [segments[0], segments[1]];
    }
    throw new Error(
      `Invalid trace ID format: ${traceId}. ` +
        `Expected format: ${TRACE_ID_V4_PREFIX}<location>/<trace_id>`,
    );
  }
  return [null, traceId];
}

/**
 * Construct a v4 trace ID string for the given location and OpenTelemetry trace ID.
 * @param location The trace location string (e.g., 'catalog.schema.prefix')
 * @param otelTraceId The OpenTelemetry trace ID (hex string)
 */
export function constructTraceIdV4(location: string, otelTraceId: string): string {
  return `${TRACE_ID_V4_PREFIX}${location}/${otelTraceId}`;
}

/**
 * Generate a v3 trace ID string ('tr-<otelTraceId>') for the given OpenTelemetry trace ID.
 * @param otelTraceId The OpenTelemetry trace ID (hex string)
 */
export function generateTraceIdV3(otelTraceId: string): string {
  return `${TRACE_ID_PREFIX}${otelTraceId}`;
}
