 * Utilities for resolving Unity Catalog trace destinations from experiment tags.
 */

/**
 * Experiment tag key for the Unity Catalog destination path ('catalog.schema.prefix').
 */
export const DATABRICKS_TRACE_DESTINATION_PATH_TAG =
  'mlflow.experiment.databricksTraceDestinationPath';

/**
 * Experiment tag key for the OTLP spans storage table name.
 */
export const DATABRICKS_TRACE_SPAN_STORAGE_TABLE_TAG =
  'mlflow.experiment.databricksTraceSpanStorageTable';

/**
 * Experiment tag key for the OTLP logs storage table name.
 */
export const DATABRICKS_TRACE_LOG_STORAGE_TABLE_TAG =
  'mlflow.experiment.databricksTraceLogStorageTable';

/**
 * Experiment tag key for the annotations table name.
 */
export const DATABRICKS_TRACE_ANNOTATIONS_TABLE_TAG =
  'mlflow.experiment.databricksTraceAnnotationsTable';

/**
 * Resolved Unity Catalog location derived from experiment tags.
 */
export interface UcLocationFromTags {
  catalogName: string;
  schemaName: string;
  tablePrefix: string;
  otelSpansTableName: string;
  otelLogsTableName: string;
  annotationsTableName: string;
}

/**
 * Resolve a Unity Catalog trace destination from a set of experiment tags.
 *
 * Reads DATABRICKS_TRACE_DESTINATION_PATH_TAG, splits it by '.', and returns null if the
 * tag is absent, the path does not have exactly three segments, or any segment is empty.
 * On success, returns an object populated from the destination path and the accompanying
 * storage/annotations table tags.
 *
 * @param tags Experiment tags
 */
export function ucLocationFromExperimentTags(
  tags: Record<string, string>,
): UcLocationFromTags | null {
  const destinationPath = tags[DATABRICKS_TRACE_DESTINATION_PATH_TAG];
  if (!destinationPath) {
    return null;
  }

  const segments = destinationPath.split('.');
  if (segments.length !== 3 || segments.some((segment) => !segment)) {
    return null;
  }

  const [catalogName, schemaName, tablePrefix] = segments;
  return {
    catalogName,
    schemaName,
    tablePrefix,
    otelSpansTableName: tags[DATABRICKS_TRACE_SPAN_STORAGE_TABLE_TAG],
    otelLogsTableName: tags[DATABRICKS_TRACE_LOG_STORAGE_TABLE_TAG],
    annotationsTableName: tags[DATABRICKS_TRACE_ANNOTATIONS_TABLE_TAG],
  };
}
