      // Set the last active trace ID
      traceManager.lastActiveTraceId = trace.info.traceId;

      // Export trace info and spans to Unity Catalog and track the promise
      const exportPromise = this.exportTraceToUc(trace.info, spans).catch((error) => {
        console.error(`Failed to export trace ${trace.info.traceId}:`, error);
      });
      this._pendingExports[trace.info.traceId] = exportPromise;
    }

    resultCallback({ code: ExportResultCode.SUCCESS });
  }

  /**
   * Export a complete trace to Unity Catalog.
   * Step 1: Create trace info via the V4 endpoint.
   * Step 2: Export the OTLP spans to the resolved UC spans table.
