      const [location, otelTraceId] = parseTraceIdV4(traceInfo.traceId);
      if (!location) {
        throw new Error(`Invalid v4 trace ID for Unity Catalog export: ${traceInfo.traceId}`);
      }

      // Step 1: Create trace info in the backend (V4 endpoint)
      const createdInfo = await this._client.createTraceInfoV4(location, otelTraceId, traceInfo);

      // Step 2: Export the OTLP spans to the UC spans table returned by the backend
      const tableName =
        getOtelSpansTableName(createdInfo.traceLocation) ??
        getOtelSpansTableName(traceInfo.traceLocation);
      if (tableName) {
        await this._client.exportOtlpSpansToUc(spans, tableName);
